def sampled_split(g, corners, at):
    """Keep a contact-family arc join only when its two pieces are resolvable.

    Analytic corner records and evaluation are unchanged. The new contact
    family can approach a single circle with a sub-micrometre arc. A separate
    wire vertex there conflicts with the existing 1 micrometre contact guard.
    Only joins within 4 micrometres of an analytic endpoint are omitted from
    sampling; existing boundary-error and complete geometry checks still apply.
    Other continuation families retain their original exact split sample.
    """
    paired=g.math('COMPARE',c._read(g,corners,'st_ct_kind',at,'INT'),2.)
    radius=c._read(g,corners,'st_cc_radius',at)
    shortest=radius*g.math('MINIMUM',g.math('ABSOLUTE',c._read(g,corners,'st_cc_sweep',at)),
                          g.math('ABSOLUTE',c._read(g,corners,'st_ct_sweep_b',at)))
    family=c._read(g,corners,'st_cj_contact_transition',at,'BOOLEAN')
    return paired*c.choose(g,family,g.math('GREATER_THAN',shortest,4e-6),True,'BOOLEAN')


def length(g, corners, at):
    read=lambda key,kind='FLOAT':c._read(g,corners,key,at,kind)
    kind=read('st_ct_kind','INT');radius=read('st_cc_radius')
    ordinary=radius*g.math('ABSOLUTE',read('st_cc_sweep'))
    pair=ordinary+radius*g.math('ABSOLUTE',read('st_ct_sweep_b'))
    line=c._length(g,c._sub(c._vec(g,read('st_cc_contact_b','FLOAT_VECTOR')),
                           c._vec(g,read('st_cc_contact_a','FLOAT_VECTOR'))))
    return c.choose(g,g.math('COMPARE',kind,1.),line,c.choose(g,g.math('COMPARE',kind,2.),pair,ordinary))


def jet(g, corners, at, fraction, total_rate):
    read=lambda key,kind='FLOAT':c._read(g,corners,key,at,kind)
    kind=read('st_ct_kind','INT');radius=read('st_cc_radius')
    pa,pb,ca,cb,joint=[c._vec(g,read(key,'FLOAT_VECTOR')) for key in
        ('st_cc_contact_a','st_cc_contact_b','st_cc_center','st_ct_second_center','st_ct_join')]
    wa,wb=read('st_cc_sweep'),read('st_ct_sweep_b')
    la=radius*g.math('ABSOLUTE',wa);lb=radius*g.math('ABSOLUTE',wb)
    pair=g.math('COMPARE',kind,2.);line=g.math('COMPARE',kind,1.)
    distance=fraction*(la+c.choose(g,pair,lb,0.))
    def arc(center,start,sweep,q,arc_length):
        radial=c._sub(start,center)
        angle=g.math('ARCTAN2',radial[1],radial[0])+sweep*c.bounded(g,q)
        rate=sweep*total_rate/g.math('MAXIMUM',arc_length,1e-12)
        point=c._add(center,c._scale([g.math('COSINE',angle),g.math('SINE',angle)],radius))
        derivative=c._scale([-g.math('SINE',angle),g.math('COSINE',angle)],radius*rate)
        return point,derivative,rate
    a,da,ka=arc(ca,pa,wa,distance/g.math('MAXIMUM',la,1e-12),la)
    b,db,kb=arc(cb,joint,wb,(distance-la)/g.math('MAXIMUM',lb,1e-12),lb)
    second=pair*g.math('GREATER_THAN',distance,la)
    point=c._pick(g,second,b,a);derivative=c._pick(g,second,db,da);turn=c.choose(g,second,kb,ka)
    delta=c._sub(pb,pa);line_point=c._add(pa,c._scale(delta,fraction))
    line_derivative=c._scale(delta,g.math('DIVIDE',total_rate,g.math('MAXIMUM',c._length(g,delta),1e-12)))
    return c._pick(g,line,line_point,point),c._pick(g,line,line_derivative,derivative),c.choose(g,line,0.,turn)


def exact_projection(g,corners,mouths,at,point):
    """Nearest admissible analytic arc/line projection, for Newton recovery.

    Candidate angles must lie on their finite arcs. This does not replace
    projection on the original curved curb pieces or excuse a failed check.
    """
    read=lambda key,kind='FLOAT':c._read(g,corners,key,at,kind)
    kind=read('st_ct_kind','INT');radius=read('st_cc_radius')
    nxt=g.math('MODULO',at+1.,c._count(g,mouths))
    la=g.math('ABSOLUTE',c._read(g,mouths,'st_cj_parameter',at)-read('st_cc_sa'))
    lb=g.math('ABSOLUTE',c._read(g,mouths,'st_cj_parameter',nxt)-read('st_cc_sb'))
    lc=length(g,corners,at);total=la+lc+lb
    pa,pb,ca,cb,joint=[c._vec(g,read(key,'FLOAT_VECTOR')) for key in
        ('st_cc_contact_a','st_cc_contact_b','st_cc_center','st_ct_second_center','st_ct_join')]
    wa,wb=read('st_cc_sweep'),read('st_ct_sweep_b');first_length=radius*g.math('ABSOLUTE',wa)
    choices=[]
    for center,start,sweep,offset,enabled in ((ca,pa,wa,0.,1.-g.math('COMPARE',kind,1.)),
                                             (cb,joint,wb,first_length,g.math('COMPARE',kind,2.))):
        radial=c._sub(start,center);delta=c._sub(point,center)
        angle=g.math('ARCTAN2',c._cross(radial,delta),c._dot(radial,delta))
        q=g.math('DIVIDE',angle,sweep)
        valid=enabled*g.math('GREATER_THAN',g.math('ABSOLUTE',sweep),1e-6)
        valid=valid*g.math('GREATER_THAN',q,-1e-7)*g.math('LESS_THAN',q,1.+1e-7)*g.math('GREATER_THAN',c._length(g,delta),1e-8)
        closest=c._add(center,c._scale(c._unit(g,delta),radius))
        d=c._sub(point,closest)
        choices.append((valid,(la+offset+c.bounded(g,q)*radius*g.math('ABSOLUTE',sweep))/total,c._dot(d,d)))
    axis=c._sub(pb,pa);q=c._dot(c._sub(point,pa),axis)/g.math('MAXIMUM',c._dot(axis,axis),1e-12)
    valid=g.math('COMPARE',kind,1.)*g.math('GREATER_THAN',q,-1e-7)*g.math('LESS_THAN',q,1.+1e-7)
    d=c._sub(point,c._add(pa,c._scale(axis,q)))
    choices.append((valid,(la+c.bounded(g,q)*lc)/total,c._dot(d,d)))
    best=1e20;station=0.;found=0.
    for good,t,distance in choices:
        use=good*g.math('LESS_THAN',distance,best)
        station=c.choose(g,use,t,station);best=c.choose(g,use,distance,best);found=g.math('MAXIMUM',found,good)
    return station,found


def build(*, polyline=False):
    name='Prochitecture Streets / Opposing curb continuation candidates v1'
    if polyline:name+=' / Exact or smooth curbs v1'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name)
    for side in ('A','B'):
        g.socket('Path '+side,'NodeSocketGeometry')
        g.socket('Width '+side,'NodeSocketFloat',default=6.)
        g.socket('Offset '+side,'NodeSocketFloat',default=0.)
    g.socket('Radius','NodeSocketFloat',default=3.)
    g.socket('Input Valid','NodeSocketBool',default=False)
    g.socket('Candidates','NodeSocketGeometry','OUTPUT')
    g.socket('Candidate Count','NodeSocketInt','OUTPUT')
    inp=g.node('NodeGroupInput');radius=c.V(g,inp.outputs['Radius'])
    paths=[inp.outputs['Path '+side] for side in ('A','B')]
    widths=[c.V(g,inp.outputs['Width '+side]) for side in ('A','B')]
    offsets=[c.V(g,inp.outputs['Offset '+side])+sign*.5*width for side,sign,width in zip(('A','B'),(-1.,1.),widths)]
    lengths=[c._read(g,path,'st_cc_knot',c._count(g,path)-1.) for path in paths]
    def data(station,sign):
        jets=[c._jet(g,path,station,offset,polyline=polyline) for path,offset in zip(paths,offsets)]
        points=[c._vec(g,j['Center']) for j in jets]
        tangents=[c._vec(g,j['Tangent']) for j in jets]
        centers=[c._add(p,c._scale(c._right(t),sign*radius)) for p,t in zip(points,tangents)]
        return points,tangents,centers
    def residual(station,sign):
        centers=data(station,sign)[2];delta=c._sub(centers[1],centers[0])
        return c._dot(delta,delta)-4.*radius*radius
    origin,tangents,_=data(0.,1.)
    valid=c.V(g,inp.outputs['Input Valid'])*g.math('GREATER_THAN',radius,1e-5)*g.math('LESS_THAN',radius,1e5)
    for width in widths:valid=valid*g.math('GREATER_THAN',width,0.)*g.math('LESS_THAN',width,1e5)
    valid=valid*g.math('LESS_THAN',c._dot(*tangents),-math.cos(math.pi/6.))
    upper=g.math('MINIMUM',g.math('MINIMUM',*lengths),4.*(g.math('MAXIMUM',*widths)+2.*radius))-1e-4
    valid=valid*g.math('GREATER_THAN',upper,1e-4)
    # A genuine straight continuation has aligned endpoint jets and a common
    # curb at the original junction. A positive line span avoids degenerate
    # zero-arc knots in all downstream chart and clearance calculations.
    points,ts,_=data(radius,1.);delta=c._sub(points[1],points[0]);direction=c._unit(g,delta)
    straight=valid*g.math('LESS_THAN',radius,upper)*g.math('GREATER_THAN',c._length(g,delta),1e-5)
    straight=straight*g.math('LESS_THAN',c._length(g,c._sub(*origin)),1e-6)
    straight=straight*g.math('LESS_THAN',c._length(g,c._add(ts[0],direction)),1e-6)
    straight=straight*g.math('LESS_THAN',c._length(g,c._sub(ts[1],direction)),1e-6)
    line=c._line(g,1)
    for key,value,kind in (('st_ct_kind',1,'INT'),('st_cc_sa',radius,'FLOAT'),('st_cc_sb',radius,'FLOAT'),
        ('st_cc_radius',radius,'FLOAT'),('st_cc_contact_a',g.xyz(*points[0]),'FLOAT_VECTOR'),
        ('st_cc_contact_b',g.xyz(*points[1]),'FLOAT_VECTOR')):
        line=c._store(g,line,key,value,kind)
    line=c._select(g,line,straight)
    index=c.V(g,g.node('GeometryNodeInputIndex').outputs[0]);steps=96.
    sign=c.choose(g,g.math('LESS_THAN',index,steps),-1.,1.)
    lo=g.math('MODULO',index,steps)*upper/steps;hi=lo+upper/steps
    f_lo=residual(lo,sign);f_hi=residual(hi,sign)
    hit=valid*(1.-straight)*(1.-g.math('GREATER_THAN',f_lo*f_hi,0.))
    seeds=c._line(g,192)
    for key,value in (('lo',lo),('hi',hi),('sign',sign),('f_lo',f_lo),('hit',hit)):
        seeds=c._store(g,seeds,'_ct_'+key,value)
    seeds=c._select(g,seeds,c.named(g,'_ct_hit'))
    ri=g.node('GeometryNodeRepeatInput','Bracketed fixed-radius circle-center contact')
    ro=g.node('GeometryNodeRepeatOutput');ri.pair_with_output(ro)
    ri.inputs['Iterations'].default_value=28;g.bind(seeds,ri.inputs['Geometry'])
