    middle=.5*(lo+hi);fm=residual(middle,sign);right=g.math('GREATER_THAN',c.named(g,'_ct_f_lo')*fm,0.)
    query=c._store(g,ri.outputs['Geometry'],'_ct_next_lo',c.choose(g,right,middle,lo))
    query=c._store(g,query,'_ct_next_hi',c.choose(g,right,hi,middle))
    query=c._store(g,query,'_ct_next_f',c.choose(g,right,fm,c.named(g,'_ct_f_lo')))
    for target,source in (('lo','next_lo'),('hi','next_hi'),('f_lo','next_f')):
        query=c._store(g,query,'_ct_'+target,c.named(g,'_ct_'+source))
    g.bind(query,ro.inputs['Geometry'])
    geo=ro.outputs['Geometry'];station=.5*(c.named(g,'_ct_lo')+c.named(g,'_ct_hi'));sign=c.named(g,'_ct_sign')
    points,ts,centers=data(station,sign);pa,pb=points;ca,cb=centers;joint=c._scale(c._add(ca,cb),.5)
    va=c._sub(pa,ca);vj=c._sub(joint,ca);vb=c._sub(pb,cb);vk=c._sub(joint,cb)
    wa=g.math('ARCTAN2',c._cross(va,vj),c._dot(va,vj));wb=g.math('ARCTAN2',c._cross(vk,vb),c._dot(vk,vb))
    error=g.math('ABSOLUTE',c._length(g,c._sub(cb,ca))-2.*radius)
    good=valid*g.math('GREATER_THAN',station,1e-5)*g.math('LESS_THAN',error,2e-5)
