    g.bind(geo,merge.inputs['Geometry'])
    join=g.node('GeometryNodeJoinGeometry');g.bind(merge.outputs['Geometry'],join.inputs['Geometry']);g.bind(line,join.inputs['Geometry'])
    out=g.node('NodeGroupOutput');g.bind(join.outputs['Geometry'],out.inputs['Candidates']);g.bind(c._count(g,join.outputs['Geometry']),out.inputs['Candidate Count'])
    return g.g
